1	package memoryloop
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"strings"
8		"time"
9		"unicode"
10	
11		"github.com/entireio/cli/cmd/entire/cli/improve"
12		"github.com/entireio/cli/cmd/entire/cli/insightsdb"
13		"github.com/entireio/cli/cmd/entire/cli/llmcli"
14	)
15	
16	const defaultMemorySlug = "memory"
17	
18	const confidenceHigh = "high"
19	const confidenceLow = "low"
20	const confidenceMedium = "medium"
21	
22	const DefaultMaxRecords = 10
23	
24	var genericAdvicePhrases = []string{
25		"always think before making changes",
26		"be careful",
27		"be mindful",
28		"double check",
29		"pay attention",
30		"think before making changes",
31	}
32	
33	var generatedSpecificityMarkers = []string{
34		".entire",
35		".go",
36		".json",
37		".md",
38		".sh",
39		"agent",
40		"branch",
41		"checkpoint",
42		"ci",
43		"claude",
44		"cmd/",
45		"commit",
46		"entire",
47		"file",
48		"files",
49		"git",
50		"gofmt",
51		"golangci",
52		"hook",
53		"json",
54		"lint",
55		"memory",
56		"memories",
57		"path",
58		"paths",
59		"prompt",
