85	type generateRecord struct {
86		Kind             Kind     `json:"kind"`
87		Title            string   `json:"title"`
88		Body             string   `json:"body"`
89		SkillName        string   `json:"skill_name,omitempty"`
90		SkillPath        string   `json:"skill_path,omitempty"`
91		Why              string   `json:"why"`
92		Evidence         []string `json:"evidence"`
93		SourceSessionIDs []string `json:"source_session_ids"`
94		Confidence       string   `json:"confidence"`
95		Strength         int      `json:"strength"`
96	}
