		default:
			if !lastDash {
				b.WriteByte('-')
				lastDash = true
			}
		}
	}
	slug := strings.Trim(b.String(), "-")
	if slug == "" {
		slug = defaultMemorySlug
	}
	return fmt.Sprintf("%s-%s", kind, slug)
}

