)

const defaultMemorySlug = "memory"

const confidenceHigh = "high"
const confidenceLow = "low"
const confidenceMedium = "medium"

const DefaultMaxRecords = 10

var genericAdvicePhrases = []string{
	"always think before making changes",
	"be careful",
	"be mindful",
