func TestLoadSummarySessions_CapsToMostRecent200(t *testing.T) {
	tmpDir := t.TempDir()
	setupSummaryTestRepo(t, tmpDir)

	now := time.Date(2026, time.April, 2, 12, 0, 0, 0, time.UTC)
	for i := range 205 {
